package runner

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/toolcall"
	"github.com/sloprail/harness-mocks/internal/tools"
)

// toolName is how hooks name the shell tool.
const toolName = "Bash"

// toolHost is Codex's side of a tool call: one shell tool, its hooks, and
// the words it tells the agent in.
type toolHost struct{ *state }

// Tool: the one tool the mock runs is the shell, which needs a command.
func (h toolHost) Tool(name string) ([]string, bool) { return []string{"command"}, name == toolName }

func command(c toolcall.Call) string {
	var in struct {
		Command string `json:"command"`
	}
	_ = json.Unmarshal(c.Input, &in)
	return in.Command
}

func (h toolHost) payload(c toolcall.Call) map[string]any {
	return map[string]any{"turn_id": h.turnID, "tool_name": toolName, "tool_use_id": c.ID,
		"tool_input": map[string]string{"command": command(c)}}
}

// Before fires PreToolUse and asks for the refusal of what the hooks decided.
func (h toolHost) Before(ctx context.Context, c toolcall.Call) (bool, string) {
	var ds []hooks.Decision
	for _, o := range h.hooks.Fire(ctx, hooks.PreToolUse, toolName, h.payload(c)) {
		ds = append(ds, hooks.Interpret(hooks.PreToolUse, o))
	}
	return hooks.Refusal(ds)
}

// Execute runs the command and shows it in the event stream.
func (h toolHost) Execute(ctx context.Context, c toolcall.Call) toolcall.Result {
	cmd := command(c)
	id := h.events.CommandStarted(cmd)
	r := tools.Bash(ctx, cmd, h.cfg.Cwd, h.toolEnv)
	h.events.CommandCompleted(id, cmd, r.Output, r.ExitCode)
	return toolcall.Result{Output: r.Output, Failed: r.Failed()}
}

// After fires PostToolUse, which Codex fires for every command that ran,
// whatever its exit status; a hook that blocks (exit 2, or a block decision)
// gives the agent its feedback in place of the result.
// sr:provides posttooluse-payload/codex
func (h toolHost) After(ctx context.Context, c toolcall.Call, r toolcall.Result, _ corehooks.AfterTool) (string, bool) {
	own := h.payload(c)
	own["tool_response"] = r.Output
	for _, o := range h.hooks.Fire(ctx, hooks.PostToolUse, toolName, own) {
		d := hooks.Interpret(hooks.PostToolUse, o)
		if d.Context != "" {
			h.rollout.Developer(d.Context)
		}
		switch {
		case d.Blocked:
			return d.BlockReason, true
		case d.Denied:
			return d.DenyReason, true
		}
	}
	return "", false
}

// Answer records what the agent was told, in Codex's words.
func (h toolHost) Answer(c toolcall.Call, a toolcall.Answer) {
	var text string
	switch a.Kind {
	case toolcall.Unknown:
		text = "unsupported call: " + c.Name
	case toolcall.Invalid:
		text = fmt.Sprintf("failed to parse function arguments: missing field `%s`", a.Missing[0])
	case toolcall.Refused:
		text = fmt.Sprintf("Command blocked by PreToolUse hook: %s. Command: %s", a.Reason, command(c))
		fmt.Fprintf(h.cfg.Stderr, "ERROR codex_core::tools::router: error=%s\n", text)
	case toolcall.Done:
		text = a.Result.Output
		if a.Replaced {
			text = a.Feedback
			fmt.Fprintf(h.cfg.Stderr, "ERROR codex_core::tools::router: error=%s\n", text)
		}
	}
	h.rollout.ToolOutput(c.ID, text)
}
package tasks

import (
	"context"
	"sync"
)

// Registry is a session's background tasks. Sub-agents share their parent's:
// what is listed as running is the whole session's, while a finished task is
// handed to the agent that launched it.
type Registry struct {
	mu      sync.Mutex
	tasks   []*Task
	changed chan struct{} // signalled (non-blocking) whenever a task finishes
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
}

// NewRegistry is an empty registry.
func NewRegistry() *Registry {
	ctx, cancel := context.WithCancel(context.Background())
	return &Registry{changed: make(chan struct{}, 1), ctx: ctx, cancel: cancel}
}

// Context is cancelled when the registry shuts down; background sub-agents run
// under it.
func (r *Registry) Context() context.Context { return r.ctx }

// has reports whether the registry holds an unfinished task with this id; a nil
// registry holds none.
func (r *Registry) has(id string) bool {
	if r == nil {
		return false
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, t := range r.tasks {
		if t.ID == id && !t.Finished() {
			return true
		}
	}
	return false
}

// Add registers a task, in launch order.
func (r *Registry) Add(t *Task) {
	r.mu.Lock()
	r.tasks = append(r.tasks, t)
	r.mu.Unlock()
}

// Go runs fn concurrently, tracked so Shutdown waits for it.
func (r *Registry) Go(fn func()) {
	r.wg.Add(1)
	go func() {
		defer r.wg.Done()
		fn()
	}()
}

// Finish marks t ended and wakes anyone waiting for a task to finish.
func (r *Registry) Finish(t *Task) {
	close(t.done)
	select {
	case r.changed <- struct{}{}:
	default:
	}
}

// Running is the session's still-running tasks, in launch order.
func (r *Registry) Running() []*Task {
	if r == nil {
		return nil
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	var out []*Task
	for _, t := range r.tasks {
		if !t.Finished() {
			out = append(out, t)
		}
	}
	return out
}

// AgentsRunning reports whether owner has a background agent still running.
func (r *Registry) AgentsRunning(owner string) bool {
	if r == nil {
		return false
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, t := range r.tasks {
		if t.Owner == owner && t.Kind == Agent && !t.Finished() {
			return true
		}
	}
	return false
}

// Package runner is one `codex exec` run: the session, its hooks, and the turn.
package runner

import (
	"context"
	"errors"
	"fmt"
	"io"
	"time"

	"github.com/sloprail/harness-mocks/codex-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/codex-mock/internal/events"
	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/codex-mock/internal/session"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// Config is everything a run is told, read once at the entrypoint.
type Config struct {
	// Script is the scenario script that drives the agent.
	Script string
	Prompt string
	// Cwd is the session's working directory.
	Cwd string
	// CodexHome holds the user's hooks.json and the session's rollout.
	CodexHome string
	Model     string
	// Environ is the environment the mock was started with.
	Environ []string
	// JSON prints the event stream on Stdout; otherwise Stdout gets the
	// agent's final message.
	JSON           bool
	Stdout, Stderr io.Writer
}

// state is the state of one run, shared by Codex's side of the turn and of
// its tool calls.
type state struct {
	cfg     Config
	id      string
	turnID  string
	hooks   *hooks.Invoker
	events  *events.Stream
	rollout *session.File
	toolEnv []string
}

// Run starts the session, fires SessionStart, and runs one turn.
// sr:provides session-start-hook/codex
// sr:provides session-end-hook/codex
// sr:provides noninteractive-run/codex
func Run(ctx context.Context, cfg Config) error {
	if cfg.Script == "" {
		return errors.New("codex-mock: a scenario script is required (--script or A10N_MOCK_SCRIPT)")
	}
	hookCfg, err := hooks.Load(cfg.CodexHome, cfg.Cwd)
	if err != nil {
		return fmt.Errorf("codex-mock: cannot load hooks: %w", err)
	}
	id := coresession.NewID()
	rollout, err := session.Create(cfg.CodexHome, id, cfg.Cwd, time.Now())
	if err != nil {
		return fmt.Errorf("codex-mock: cannot create the session file: %w", err)
	}
	defer rollout.Close()
	out := cfg.Stdout
	if !cfg.JSON {
		out = io.Discard
	}
	s := &state{cfg: cfg, id: id, turnID: coresession.NewID(), rollout: rollout, events: events.New(out),
		toolEnv: childenv.ToolEnv(cfg.Environ, id)}
	s.hooks = &hooks.Invoker{Config: hookCfg, Dir: cfg.Cwd, Environ: cfg.Environ, Ident: childenv.HookIdentity(),
		Common: hooks.Common{SessionID: id, TranscriptPath: rollout.Path, Cwd: cfg.Cwd, Model: cfg.Model,
			PermissionMode: "bypassPermissions"}}
	s.events.ThreadStarted(id)
	for _, o := range s.hooks.Fire(ctx, hooks.SessionStart, "startup", map[string]any{"source": "startup"}) {
		if d := hooks.Interpret(hooks.SessionStart, o); d.Context != "" {
			rollout.Developer(d.Context)
		}
	}
	s.events.TurnStarted()
	last, err := turnloop.Run(ctx, turnHost{s}, turnloop.Params{
		Script: cfg.Script, Dir: cfg.Cwd, Environ: cfg.Environ, Prompt: cfg.Prompt})
	s.events.TurnCompleted()
	// The session ends with the run, for the one reason a non-interactive run has;
	// what the hook prints is not read.
	s.hooks.Fire(ctx, hooks.SessionEnd, "other", map[string]any{"reason": "other"})
	if !cfg.JSON && last != "" {
		fmt.Fprintln(cfg.Stdout, last)
	}
	return err
}

// newID is a random identifier in the shape of a version 4 UUID.
package runner

import (
	"context"
	"fmt"
	"strings"

	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/scenario"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// turnHost is Codex's side of a turn: its prompt and end-of-turn hooks, and
// its record of what was said.
type turnHost struct{ *state }

// SubmitPrompt fires UserPromptSubmit: the context the hooks add (plain text
// or additionalContext), and whether one blocked the prompt (exit 2, or a block
// decision).
// sr:provides user-prompt-submit-hook/codex
// sr:provides hook-additional-context/codex
func (h turnHost) SubmitPrompt(ctx context.Context) (string, bool) {
	var texts []string
	blocked := false
	own := map[string]any{"turn_id": h.turnID, "prompt": h.cfg.Prompt}
	for _, o := range h.hooks.Fire(ctx, hooks.UserPromptSubmit, "", own) {
		d := hooks.Interpret(hooks.UserPromptSubmit, o)
		blocked = blocked || d.Blocked || d.Denied
		if d.Context != "" {
			texts = append(texts, d.Context)
			h.rollout.Developer(d.Context)
		}
	}
	if !blocked {
		h.rollout.User(h.cfg.Prompt)
	}
	return strings.Join(texts, "\n"), blocked
}

// Say shows a message of the agent in the event stream and the rollout.
func (h turnHost) Say(text string) {
	h.events.AgentMessage(text)
	h.rollout.Assistant(text)
}

// Tool records the agent's call, and carries it out.
func (h turnHost) Tool(ctx context.Context, tu scenario.ToolUse) {
	h.rollout.ToolCall(tu.ID, tu.Name, tu.Input)
	toolcall.Run(ctx, toolHost{h.state}, toolcall.Call{ID: tu.ID, Name: tu.Name, Input: tu.Input},
		toolcall.Options{SeparateFailureHook: false})
}

// EndOfTurn fires Stop. A hook that blocks (exit 2, or a block decision) asks
// for the turn to continue; the first one's reason is the new prompt.
// sr:provides stop-block-continuation/codex
// sr:provides stop-hook-payload/codex
func (h turnHost) EndOfTurn(ctx context.Context, last string, continuing bool) (string, bool) {
	own := map[string]any{"turn_id": h.turnID, "stop_hook_active": continuing, "last_assistant_message": last}
	for _, o := range h.hooks.Fire(ctx, hooks.Stop, "", own) {
		d := hooks.Interpret(hooks.Stop, o)
		switch {
		case d.Blocked:
			return d.BlockReason, true
		case d.Denied:
			return d.DenyReason, true
		}
	}
	return "", false
}

// Continue records the reason that continues the turn, as the user message
// Codex makes of it.
func (h turnHost) Continue(reason string) {
	h.rollout.User(fmt.Sprintf(`<hook_prompt hook_run_id="stop">%s</hook_prompt>`, reason))
}

// SessionFile is the rollout the script reads.
func (h turnHost) SessionFile() string { return h.rollout.Path }

// CapOverridden: Codex has no cap on end-of-turn blocks (the run passes none),
// so this is never called.
func (h turnHost) CapOverridden(int) {}
package tasks

import (
	"context"
	"io"
	"os"

	"github.com/sloprail/harness-mocks/internal/procexec"
)

// CommandSpec is a shell command to run in the background.
type CommandSpec struct {
	// Argv is the program and its arguments; Dir and Env its working directory
	// and whole environment.
	Argv []string
	Dir  string
	Env  []string
	// Out is the file the command's stdout and stderr go to; it is closed when
	// the command ends.
	Out *os.File
	// Trailer is what is appended to Out when the command ends: how it ended
	// (the exit code, or that it was killed). Nil appends nothing.
	Trailer func(exitCode int, killed bool) string
	// Started runs once the task is registered, before anything of its end can
	// happen; Ended runs once the command has ended and Out is closed, before
	// the task is finished.
	Started, Ended func(*Task)
}

// StartCommand starts the command for t in the background and registers t. The
// command is not bound to the turn that started it, so it keeps running while
// the agent works; it has its own process group, so ending it reaches whatever
// it spawned. t.ExitCode is set when it ends.
func (r *Registry) StartCommand(t *Task, s CommandSpec) error {
	p, err := procexec.Start(procexec.Spec{Argv: s.Argv, Dir: s.Dir, Env: s.Env}, s.Out)
	if err != nil {
		s.Out.Close()
		return err
	}
	t.Kind = Command
	t.kill = p.Kill
	r.Add(t)
	if s.Started != nil {
		s.Started(t)
	}
	r.Go(func() {
		t.ExitCode = p.Wait()
		if s.Trailer != nil {
			io.WriteString(s.Out, s.Trailer(t.ExitCode, t.Killed())) //nolint:errcheck
		}
		s.Out.Close()
		if s.Ended != nil {
			s.Ended(t)
		}
		r.Finish(t)
	})
	return nil
}

// StartAgent registers a background agent t and runs it concurrently with the
// turn that launched it: run returns when the agent has ended, and the caller
// has already answered the launch.
//
// sr:capability background-agent
func (r *Registry) StartAgent(t *Task, run func(ctx context.Context)) {
	t.Kind = Agent
	r.Add(t)
	r.Go(func() {
		run(r.ctx)
		r.Finish(t)
	})
}

// RunsInBackground reports whether a command or sub-agent that asked to run in
// the background does: it does not when the harness has background tasks
// turned off, and then it runs in the foreground like any other. It is the
// entry to background-bash: StartCommand runs what this lets through.
//
// sr:capability background-bash
func RunsInBackground(asked, disabled bool) bool {
	return asked && !disabled
}
// Package tasks is the harness-neutral core of background tasks: starting them,
// tracking what is running, handing finished ones to their owner, and ending
// them.
package tasks

import (
	"sync/atomic"
	"time"
)

// Kind is what a task is.
type Kind int

const (
	// Command is a shell command running in the background.
	Command Kind = iota
	// Agent is a sub-agent running in the background.
	Agent
)

// Status is how a finished task ended.
type Status string

const (
	Completed Status = "completed"
	Failed    Status = "failed"
	// Stopped is a command ended by the harness (killed), not by itself.
	Stopped Status = "stopped"
)

// Task is one background task. The first fields are its identity and what a
// harness reports of it; the outcome fields are set before the task finishes.
type Task struct {
	ID, ToolUseID string
	// Owner is the agent that launched the task, "" for the main thread: the
	// owner is the one told when the task finishes.
	Owner       string
	Kind        Kind
	Description string
	// Command is a Command task's command line, AgentType an Agent task's type.
	Command, AgentType string
	OutputFile         string
	Started            time.Time

	// Meta is what the harness attaches for its own reports of the task (its
	// stream frames); the core never reads it.
	Meta any

	// ExitCode is a Command's exit status (also 1 for a failed Agent).
	ExitCode int
	// Result, Failure, ToolUses and DurationMs are an Agent's outcome.
	Result, Failure string
	ToolUses        int
	DurationMs      int64

	done      chan struct{}
	killed    atomic.Bool
	kill      func()
	delivered bool // guarded by Registry.mu
}

// NewTask is a task not yet started.
func NewTask(kind Kind, id string) *Task {
	return &Task{ID: id, Kind: kind, Started: time.Now(), done: make(chan struct{})}
}

// Finished reports whether the task has ended.
func (t *Task) Finished() bool {
	select {
	case <-t.done:
		return true
	default:
		return false
	}
}

// Done is closed when the task ends.
func (t *Task) Done() <-chan struct{} { return t.done }

// Killed reports whether the harness ended the task.
func (t *Task) Killed() bool { return t.killed.Load() }

// Status is how the task ended: stopped when the harness killed it, failed for
// a command with a non-zero exit or an agent that failed, else completed.
func (t *Task) Status() Status {
	switch {
	case t.Killed():
		return Stopped
	case t.Kind == Agent && t.Failure != "":
		return Failed
	case t.Kind == Command && t.ExitCode != 0:
		return Failed
	}
	return Completed
}
# A module is an area of code with a boundary; its decisions live here, not in an ADR.
# No core yet (internal/tasks): the code lives in the claude-mock files below, until it moves.
concern: "background tasks: launching, tracking, delivering their notifications and killing them"
home: ["internal/tasks/**", "claude-mock/internal/runner/background*.go"]   # everything about the concern lives here
api: ["internal/tasks"]       # the only packages others may import
package e2e

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

const runsDir = "../../snapshots/runs"

// recording is one recorded sample of a real `codex exec` run.
type recording struct {
	setup  string   // runs/<name>/setup
	sample string   // runs/<name>/samples/<ts>
	calls  []string // the shell commands the model asked for, in order
}

func loadRecording(t *testing.T, name string) recording {
	t.Helper()
	samples, err := filepath.Glob(filepath.Join(runsDir, name, "samples", "*"))
	require.NoError(t, err)
	require.NotEmpty(t, samples, "no recorded sample of run %s", name)
	rec := recording{setup: filepath.Join(runsDir, name, "setup"), sample: samples[len(samples)-1]}
	seen := map[string]bool{}
	for _, p := range jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))) {
		id, _ := p["tool_use_id"].(string)
		if p["hook_event_name"] == "PreToolUse" && !seen[id] {
			seen[id] = true
			in, _ := p["tool_input"].(map[string]any)
			rec.calls = append(rec.calls, in["command"].(string))
		}
	}
	if len(rec.calls) == 0 { // no before-tool hook logged: the commands that ran are the calls
		rec.calls, _ = result{Stdout: readFile(t, filepath.Join(rec.sample, "stream.jsonl"))}.commands()
	}
	return rec
}

func readFile(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return ""
	}
	require.NoError(t, err)
	return string(b)
}

// replay runs the mock on the recorded run's own setup (its hooks.json, its
// hook script, its prompt), with a script that makes the calls the model made.
func replay(t *testing.T, rec recording, extraEnv ...string) result {
	t.Helper()
	return execMock(t, scenario{
		HooksJSON: readFile(t, filepath.Join(rec.setup, "hooks.json")),
		Files:     map[string]string{"hook.sh": readFile(t, filepath.Join(rec.setup, "hook.sh"))},
		Script:    callThenResult,
		Prompt:    strings.TrimSpace(readFile(t, filepath.Join(rec.setup, "prompt.txt"))),
		Env:       append(withCalls(t, rec.calls...), extraEnv...),
	})
}

// normalized is what a hook payload shows of what a scenario did, without what
// differs between two runs of the same behaviour (ids, paths, timings, the
// model's name, the OS's wording of an error): the same removals capture.sh makes.
func normalized(v any, sid string) any {
	switch x := v.(type) {
	case map[string]any:
		for _, k := range []string{"transcript_path", "cwd", "turn_id", "tool_use_id", "uuid", "timestamp", "duration_ms", "last_assistant_message", "model"} {
			delete(x, k)
		}
		if in, ok := x["tool_input"].(map[string]any); ok {
			delete(in, "description")
		}
		for k, e := range x {
			x[k] = normalized(e, sid)
		}
	case string:
		if strings.Contains(x, "No such file or directory") {
			return "<ENOENT>"
		}
		return strings.ReplaceAll(x, sid, "<SESSION_ID>")
	}
	return v
}

func sortedHookLines(lines []map[string]any) []string {
	var sid string
	for _, l := range lines {
		if s, ok := l["session_id"].(string); ok {
			sid = s
			break
		}
	}
	var out []string
	for _, l := range lines {
		b, _ := json.Marshal(normalized(l, sid))
		out = append(out, string(b))
	}
	sort.Strings(out)
	return out
}

// Every recorded run of the hooks a `codex exec` fires, replayed: the mock's
// hooks see the same payloads, and the hook scripts take the same exits; the
// event stream shows the same commands, run to the same exit statuses and
// outputs, in the same order (a command a hook refused is in neither).
// sr:proves hook-exit-code-semantics/codex
// sr:proves pretooluse-refusal/codex
func TestReplayOfRecordedRuns(t *testing.T) {
	for _, name := range []string{"stops", "hook-exit-codes", "hook-exit-json", "hook-unstartable",
		"pretool-decisions", "prompt-blocked", "posttool-block", "hook-matchers", "hook-timeout", "session-end"} {
		t.Run(name, func(t *testing.T) {
			rec := loadRecording(t, name)
			got := replay(t, rec)
			require.Equal(t, 0, got.Code, got.Stderr)

			var want []map[string]any
			for _, l := range jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))) {
				want = append(want, l)
			}
			assert.Equal(t, sortedHookLines(want), sortedHookLines(got.hookLog()), "hook payloads and exits")

			recStream := result{Stdout: readFile(t, filepath.Join(rec.sample, "stream.jsonl"))}
			wantCmds, wantExits := recStream.commands()
			gotCmds, gotExits := got.commands()
			assert.Equal(t, wantCmds, gotCmds, "commands that ran")
			assert.Equal(t, failures(wantExits), failures(gotExits), "which of them failed (the status of ls differs between systems)")
			assert.Equal(t, streamShape(recStream.stream()), streamShape(got.stream()), "event stream")
		})
	}
}

func failures(exits []float64) []bool {
	var out []bool
	for _, e := range exits {
		out = append(out, e != 0)
	}
	return out
}

// streamShape is the event types of a stream, without the warnings and the
// messages that depend on the run's flags and the model's words.
func streamShape(events []map[string]any) []string {
	var out []string
	for _, e := range events {
		typ, _ := e["type"].(string)
		item, _ := e["item"].(map[string]any)
		if item["type"] == "error" || item["type"] == "agent_message" {
			continue
		}
		if item != nil {
			typ += ":" + item["type"].(string)
		}
		out = append(out, typ)
	}
	return out
}
package e2e

import (
	"bytes"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// scenario is one mock run: the hooks it loads, the script that drives it.
type scenario struct {
	// HooksJSON is the user layer's $CODEX_HOME/hooks.json.
	HooksJSON string
	// Files are written into the repository (a hook script, say), mode 0755.
	Files map[string]string
	// Script is the scenario script.
	Script string
	Prompt string
	// Env is added to the mock's environment.
	Env []string
	// NoJSON runs `exec` without --json, so stdout carries the final message.
	NoJSON bool
}

// result is what a run left.
type result struct {
	Repo, Home, Tmp string
	Stdout, Stderr  string
	Code            int
}

// execMock runs `exec --json` in a fresh git repository, hermetic but for the
// tools (sh, git, jq) the hooks use: no CODEX_* or CLAUDE* variable of the
// process running the tests reaches it.
func execMock(t *testing.T, s scenario) result {
	t.Helper()
	root, err := filepath.EvalSymlinks(t.TempDir())
	require.NoError(t, err)
	r := result{Repo: filepath.Join(root, "repo"), Home: filepath.Join(root, "home", ".codex"), Tmp: filepath.Join(root, "tmp")}
	for _, d := range []string{r.Repo, r.Home, r.Tmp} {
		require.NoError(t, os.MkdirAll(d, 0o755))
	}
	require.NoError(t, exec.Command("git", "-C", r.Repo, "init", "-q").Run())
	if s.HooksJSON != "" {
		require.NoError(t, os.WriteFile(filepath.Join(r.Home, "hooks.json"), []byte(s.HooksJSON), 0o644))
	}
	for name, body := range s.Files {
		require.NoError(t, os.WriteFile(filepath.Join(r.Repo, name), []byte(body), 0o755))
	}
	script := filepath.Join(root, "scenario.sh")
	require.NoError(t, os.WriteFile(script, []byte(s.Script), 0o755))

	env := []string{"CODEX_HOME=" + r.Home, "TMPDIR=" + r.Tmp, "HOOK_LOG=" + filepath.Join(r.Tmp, "hook.log")}
	for _, kv := range os.Environ() {
		if !strings.HasPrefix(kv, "CODEX") && !strings.HasPrefix(kv, "CLAUDE") && !strings.HasPrefix(kv, "TMPDIR=") {
			env = append(env, kv)
		}
	}
	args := []string{"exec", "--json", "--skip-git-repo-check", "--script", script, "-m", "mock-model", s.Prompt}
	if s.NoJSON {
		args = append(args[:1], args[2:]...)
	}
	cmd := exec.Command(mockBinary, args...)
	cmd.Dir = r.Repo
	cmd.Env = append(env, s.Env...)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		var exit *exec.ExitError
		require.ErrorAs(t, err, &exit)
		r.Code = exit.ExitCode()
	}
	r.Stdout, r.Stderr = out.String(), errb.String()
	return r
}

// jsonLines parses text as JSON objects, one per line, skipping other lines.
func jsonLines(text string) []map[string]any {
	var out []map[string]any
	for _, l := range strings.Split(text, "\n") {
		var m map[string]any
		if json.Unmarshal([]byte(strings.TrimSpace(l)), &m) == nil && m != nil {
			out = append(out, m)
		}
	}
	return out
}

// hookLog is what the run's hooks wrote to $HOOK_LOG, as objects.
func (r result) hookLog() []map[string]any {
	b, _ := os.ReadFile(filepath.Join(r.Tmp, "hook.log"))
	return jsonLines(string(b))
}

// stream is the event stream the run printed.
func (r result) stream() []map[string]any { return jsonLines(r.Stdout) }

// commands are the shell commands the stream shows as run to completion, in
// order, with their exit codes.
func (r result) commands() (cmds []string, exits []float64) {
	for _, e := range r.stream() {
		item, _ := e["item"].(map[string]any)
		if e["type"] == "item.completed" && item["type"] == "command_execution" {
			cmds = append(cmds, innerCommand(item["command"].(string)))
			exits = append(exits, item["exit_code"].(float64))
		}
	}
	return
}

// innerCommand is the command inside `/bin/<shell> -c[l] '<command>'`.
func innerCommand(shellLine string) string {
	i := strings.Index(shellLine, "'")
	return strings.ReplaceAll(strings.TrimSuffix(shellLine[i+1:], "'"), `'\''`, "'")
}

// rollout is the session file the run wrote.
func (r result) rollout(t *testing.T) string {
	t.Helper()
	var text string
	require.NoError(t, filepath.Walk(filepath.Join(r.Home, "sessions"), func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() {
			b, _ := os.ReadFile(p)
			text = string(b)
		}
		return nil
	}))
	return text
}

// hooksJSON is a hooks.json with one command handler per event, all running
// the same command (the matcher is any).
func hooksJSON(command string, events ...string) string {
	h := map[string]any{}
	for _, ev := range events {
		h[ev] = []any{map[string]any{"hooks": []any{map[string]any{"type": "command", "command": command}}}}
	}
	b, _ := json.Marshal(map[string]any{"hooks": h})
	return string(b)
}

const (
	// callThenResult makes one Bash call per run of the script, taken from
	// $CALLS (one command per line), and then a final message and a result.
	callThenResult = `#!/bin/sh
n=$(grep -c function_call_output "$A10N_MOCK_SESSION_FILE")
cmd=$(sed -n "$((n+1))p" "$CALLS")
if [ -n "$cmd" ]; then
  printf '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"call_%s","name":"Bash","input":{"command":%s}}]}}\n' "$n" "$(printf '%s' "$cmd" | jq -Rs .)"
  exit 0
fi
printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"DONE"}]}}' '{"type":"result","subtype":"success","result":"DONE"}'
`
)

// withCalls is env for callThenResult: the commands it runs, in order.
func withCalls(t *testing.T, cmds ...string) []string {
	t.Helper()
	f := filepath.Join(t.TempDir(), "calls")
	require.NoError(t, os.WriteFile(f, []byte(strings.Join(cmds, "\n")+"\n"), 0o644))
	return []string{"CALLS=" + f}
}

