		HooksJSON: hooksJSON("sh hook.sh", "Stop"),
		Files:     map[string]string{"hook.sh": `cat >>"$HOOK_LOG"; echo >>"$HOOK_LOG"; if [ ! -f "$TMPDIR/once" ]; then : >"$TMPDIR/once"; echo again >&2; exit 2; fi`},
